import {chromium} from 'playwright';import {readFile,readdir,writeFile,mkdir} from 'node:fs/promises';import {resolve,relative} from 'node:path';
const root=resolve('site'),out='diagnostics/platform-runtime-audit-20261114',jobs=[],rows=[];await mkdir(out,{recursive:true});
async function walk(dir){for(const e of await readdir(dir,{withFileTypes:true})){if(['.git','node_modules','artifacts','zero-defect-smoke'].includes(e.name))continue;const p=resolve(dir,e.name);if(e.isDirectory())await walk(p);else if(e.name.endsWith('.html')){const rel=relative(root,p).replaceAll('\\','/');jobs.push(rel==='index.html'?'/':rel.endsWith('/index.html')?'/'+rel.slice(0,-10):'/'+rel);}}}await walk(root);
const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH});try{for(const width of [390,1366]){const context=await browser.newContext({viewport:{width,height:900}});let cursor=0;await Promise.all(Array.from({length:5},async()=>{while(cursor<jobs.length){const route=jobs[cursor++],page=await context.newPage(),errors=[],internalResources=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{try{if(new URL(r.url()).hostname==='hossambahr.com'&&r.status()>=400)internalResources.push({url:r.url(),status:r.status()});}catch{}});
let row={route,width};try{let response=await page.goto('https://hossambahr.com'+encodeURI(route)+'?runtimeAudit=20261114',{waitUntil:'domcontentloaded',timeout:25000});try{await page.waitForLoadState('networkidle',{timeout:8000});}catch{row.networkIdleTimedOut=true;}
const state=await page.evaluate(()=>{const visible=e=>e.getClientRects().length>0&&getComputedStyle(e).visibility!=='hidden';return {lang:document.documentElement.lang,dir:document.documentElement.dir,title:document.title,bodyText:document.body.innerText.trim().length,overflow:document.documentElement.scrollWidth>innerWidth+2,overflowElements:[...document.querySelectorAll('main *')].filter(visible).filter(e=>{const r=e.getBoundingClientRect();return r.left < -3||r.right>innerWidth+3;}).slice(0,8).map(e=>({tag:e.tagName,cls:e.className,text:e.textContent.slice(0,80)})),emptyControls:[...document.querySelectorAll('button,a[href]')].filter(visible).filter(e=>!e.textContent.trim()&&!e.getAttribute('aria-label')&&!e.getAttribute('title')&&!e.querySelector('img[alt],svg title')).slice(0,12).map(e=>({tag:e.tagName,cls:e.className,href:e.getAttribute('href')})),brokenImages:[...document.images].filter(visible).filter(e=>e.complete&&!e.naturalWidth).map(e=>e.getAttribute('src')),localMissingFragments:[...document.querySelectorAll('a[href^="#"]')].filter(visible).map(e=>e.getAttribute('href')).filter(h=>h.length>1&&!document.getElementById(decodeURIComponent(h.slice(1))))};});
row={...row,...state,status:response?.status(),finalURL:page.url(),errors,internalResources};if((row.overflow||errors.length||row.brokenImages.length)&&rows.filter(r=>r.screenshot).length<16){const name=width+'-'+rows.length+'.jpg';await page.screenshot({path:out+'/'+name,type:'jpeg',quality:75});row.screenshot=name;}
}catch(e){row.error=e.message;}rows.push(row);await page.close();}}));await context.close();}}finally{await browser.close();const summary={sourceSHA:process.env.SOURCE_SHA,captureSource:'LIVE_PRODUCTION',pageRoutes:jobs.length,cases:rows.length,overflow:rows.filter(r=>r.overflow).length,pageErrors:rows.filter(r=>r.errors?.length).length,brokenImages:rows.filter(r=>r.brokenImages?.length).length,emptyControls:rows.filter(r=>r.emptyControls?.length).length,localMissingFragments:rows.filter(r=>r.localMissingFragments?.length).length,networkErrors:rows.filter(r=>r.error).length};await writeFile(out+'/report.json',JSON.stringify({summary,rows},null,2));console.log(JSON.stringify(summary));}
